import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.io.*;
import java.nio.file.*;
import java.util.zip.*;
import java.util.Base64;
import java.net.http.*;
import java.net.URI;

public class ArchiveProcessorConsumer {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String EXTRACT_DIR = "/tmp/processing";
    private static final String METADATA_ENDPOINT = "http://169.254.169.254/latest/meta-data/iam/security-credentials/";

    private final SqsClient sqsClient;

    public ArchiveProcessorConsumer() {
        this.sqsClient = SqsClient.builder().build();
    }

    public void pollAndProcess() {
        while (true) {
            ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .build();

            for (Message msg : sqsClient.receiveMessage(request).messages()) {
                try {
                    processMessage(msg);
                    deleteMessage(msg);
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                }
            }
        }
    }

    private void processMessage(Message message) throws Exception {
        // Message body contains base64-encoded zip archive
        byte[] zipBytes = Base64.getDecoder().decode(message.body());
        Path tempZip = Files.createTempFile("archive-", ".zip");
        Files.write(tempZip, zipBytes);

        extractZipArchive(tempZip.toFile(), new File(EXTRACT_DIR));
        Files.deleteIfExists(tempZip);

        // After extraction, attempt to send results to callback
        notifyProcessingComplete(message.messageId());
    }

    /**
     * Extracts zip archive to destination directory.
     * Note: entry names are used directly for path construction.
     */
    private void extractZipArchive(File zipFile, File destDir) throws IOException {
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                // Construct output path from entry name
                String entryName = entry.getName();
                File outputFile = new File(destDir, entryName);

                // Basic check: skip if entry name starts with absolute path
                if (entryName.startsWith("/")) {
                    System.err.println("Skipping absolute path entry: " + entryName);
                    continue;
                }

                if (entry.isDirectory()) {
                    outputFile.mkdirs();
                } else {
                    outputFile.getParentFile().mkdirs();
                    try (FileOutputStream fos = new FileOutputStream(outputFile)) {
                        byte[] buffer = new byte[4096];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zis.closeEntry();
            }
        }
    }

    /**
     * Sends processing notification. In compromised scenarios,
     * an attacker could overwrite scripts that later call the metadata service
     * to exfiltrate IAM credentials.
     */
    private void notifyProcessingComplete(String messageId) {
        try {
            // Fetch IAM role name for tagging the result
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest req = HttpRequest.newBuilder()
                .uri(URI.create(METADATA_ENDPOINT))
                .timeout(java.time.Duration.ofSeconds(2))
                .GET()
                .build();
            HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());
            String roleName = resp.body().trim();

            // Fetch temporary credentials for the role
            HttpRequest credReq = HttpRequest.newBuilder()
                .uri(URI.create(METADATA_ENDPOINT + roleName))
                .timeout(java.time.Duration.ofSeconds(2))
                .GET()
                .build();
            HttpResponse<String> credResp = client.send(credReq, HttpResponse.BodyHandlers.ofString());
            System.out.println("Processing complete for " + messageId + " with role: " + roleName);
        } catch (Exception e) {
            System.err.println("Metadata fetch failed (expected in restricted envs): " + e.getMessage());
        }
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
            .queueUrl(QUEUE_URL)
            .receiptHandle(message.receiptHandle())
            .build());
    }

    public static void main(String[] args) {
        new ArchiveProcessorConsumer().pollAndProcess();
    }
}
